1	// THE UPDATE RUNNER (#768) — the shell that makes the versioned flows actually run
2	// against a member. Everything it decides was decided elsewhere: the flows judge and
3	// write, `terminalFor` says what happens to the PR, `deliveryFor` says whether the PR
4	// this run opens is the member's to land. What lives here is the I/O none of them may
5	// carry — the clone, the branch, the commit, the push, the PR, and the hand-off.
6	//
7	// SAME SHAPE AS BASELINING, deliberately. That worker is the proven pattern for
8	// "converge a member from its own Actions run": clone canon fresh, run the CLONE's
9	// scripts as subprocesses rather than the mount's stale copies, deliver on a branch,
10	// and let the shared landing helper own every nuance of arming versus merging. A
11	// second, cleverer shape here would be a second set of the same bugs.
12	//
13	// IT NO LONGER ASKS WHICH MECHANISM SERVES THE REPO. There is one, and its only
14	// rival was deleted in #768 Phase 5, so the question had exactly one answer for
15	// every member that could ask it; the `maintenance` block that held it is gone
16	// (#1252) and `engine/served-by.mjs` is deprecated with it.
17	import { execFileSync } from 'node:child_process';
18	import { readFileSync, existsSync, mkdtempSync, writeFileSync } from 'node:fs';
19	import { join } from 'node:path';
20	import { tmpdir } from 'node:os';
21	import { pathToFileURL } from 'node:url';
22	import { removeTree } from '../../../../engine/remove-tree.mjs';
23	import {
24	  deliveryFor, pullCreateError, landDelivery, openDeliveredPull, disposeOpenPull,
25	} from '../../../claudinite-tasks/public/delivery.mjs';
26	import { withTaskTrailer } from '../../../claudinite-tasks/public/work-item-grammar.mjs';
27	import { settingsPath, SETTINGS_FILE } from '../../../../engine/settings-file.mjs';
28	
29	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
30	const UPDATE_PREFIX = 'claudinite/update';
31	// What this worker stamps on everything it commits and merges (task-trailer.mjs).
32	const UPDATE_TASK_ID = 'claudinite-lifecycle/update';
33	const API = 'https://api.github.com';
34	
35	const git = (args, opts = {}) =>
36	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
37	
38	async function gh(token, path, { method = 'GET', body } = {}) {
39	  const res = await fetch(`${API}${path}`, {
40	    method,
41	    headers: {
42	      authorization: `Bearer ${token}`,
43	      accept: 'application/vnd.github+json',
44	      'x-github-api-version': '2022-11-28',
45	      ...(body ? { 'content-type': 'application/json' } : {}),
46	    },
47	    body: body ? JSON.stringify(body) : undefined,
48	  });
49	  let json = null;
50	  try { json = await res.json(); } catch { /* empty body */ }
51	  return { status: res.status, json };
52	}
53	
54	// --- pure helpers (exported, unit-tested git-free) --------------------------
55	
56	// One branch per run, dated and seeded like baselining's: two runs on one day must
57	// not collide, and a name that carries its date is one a human can read a week later.
58	// Minted only under an executor that hands no target in — see the
59	// tolerance in `main`, and #1698 for its removal.
60	export const updateBranchName = (day, seed) => `${UPDATE_PREFIX}-${day}-${seed}`;
61	
62	// The line the LIVE CANARY rehearsal greps for. A rehearsal that converges nothing
63	// and exits 0 is worse than no gate at all — it reports a qualification that never
64	// happened — and that is not hypothetical: this exact gate went vacuous the day the
65	// canary flipped to `updates`, because the workflow drove the canary's baselining
66	// worker, which correctly stood down and exited 0 in zero seconds for weeks.
67	//
68	// So the rehearsal announces that it really ran, and the workflow fails when this
69	// line is absent. Any future path that skips the converge is caught by construction
70	// rather than by someone noticing a suspiciously fast green.
71	export const REHEARSAL_MARKER = 'claudinite-rehearsal: converged';
72	
73	// Does this run UPDATE the pull request the executor named, or open one? The
74	// executor resolves `amend_existing_or_create_new_pr` before this subprocess
75	// starts and hands the number in; all this decides is whether the answer still
76	// holds by the time the branch is pushed.
77	//
78	// A named pull request that is no longer open was closed under the run. The branch
79	// is still the one to push to — it is the target the executor chose — but the
80	// delivery has to be a NEW pull request: a push onto a closed one changes nothing
81	// anybody sees, and the run would report a delivery it did not make.
82	export const amendsPull = (targetPr, pull) =>
83	  Boolean(targetPr) && pull?.state === 'open' && pull?.number === Number(targetPr);
84	
85	// The PR title and body for a terminal. The body is what a human reads when the run
86	// stopped, so it says WHICH terminal fired and why in its first line — a PR that only
87	// says "an update ran" makes every reader re-derive the thing the run already knew.
88	//
89	// THE TITLE IS A SUMMARY, THE BODY IS THE DETAIL. A title that names every moved pack
90	// grows with the number a member declares, and a PR list is where that is least
91	// readable — so the packs collapse to a count and only the engine keeps its versions.
92	export function updatePullText(terminal, { engine, packs }) {
93	  const engineMoved = engine?.from !== engine?.to;
94	  const movedPacks = (packs?.plan ?? []).filter((p) => p.from !== p.to);
95	  const moved = [
96	    ...(engineMoved ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
97	    ...movedPacks.map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
98	  ];
99	  const summary = [
100	    ...(engineMoved ? [`engine ${engine?.from == null ? 'unstamped' : `v${engine.from}`} → v${engine?.to}`] : []),
101	    ...(movedPacks.length ? [`${movedPacks.length} pack${movedPacks.length === 1 ? '' : 's'} upgraded`] : []),
102	  ];
103	  const title = summary.length ? `Claudinite update: ${summary.join(' and ')}` : 'Claudinite update';
104	  const lines = [`**${terminal.action}** — ${terminal.why}`, ''];
105	  if (moved.length) lines.push('Versions moved by this run:', ...moved.map((m) => `- ${m}`), '');
106	  else lines.push('No version moved; this run converged the mount and changed nothing else.', '');
107	  if (terminal.action === 'needs-human') {
108	    lines.push('This PR stays open. Nothing merges on a non-green terminal — see the label.');
109	  } else if (terminal.action === 'apply-stage') {
110	    lines.push('The deterministic half is done. The agent stage applies the new rules to this repo\'s own content and runs its tests over what this converge wrote, before anything merges.');
111	  }
112	  return { title, body: `${lines.join('\n')}\n` };
113	}
114	
115	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
116	
117	export async function main() {
118	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
119	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
120	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
121	  const token = process.env.GITHUB_TOKEN;
122	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
123	  // REHEARSAL MODE (the live canary): converge this repo against a NAMED canon ref,
124	  // report, and restore the working tree — no branch, no commit, no PR, and above
125	  // all no stamp. A stamped branch head would leave the canary pointing off trunk,
126	  // which is exactly what the next converge's anti-rewind guard refuses: a rehearsal
127	  // that wedges its own canary.
128	  const rehearsalRef = process.env.CLAUDINITE_CANON_REF || null;
129	  if (!repo) { console.error('update: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
130	  if (!token) { console.error('update: no GITHUB_TOKEN in env'); process.exit(1); }
131	
132	  // Either settings-file name, in the rename's read order: this worker is VENDORED,
133	  // so the copy running on a member may predate the record that renamed its own
134	  // file — and one that only knew the new name would report "nothing to update" on
135	  // every repo still carrying the old one.
136	  const settingsFile = settingsPath(root);
137	  if (!existsSync(settingsFile)) { console.log(`update: no ${SETTINGS_FILE} — nothing to update`); return; }
138	  const declaration = JSON.parse(readFileSync(settingsFile, 'utf8'));
139	
140	  // One override, one direction: a repo that asked for review gets its PR opened and
141	  // left; every other repo — the normal shape, the key absent — has it landed.
142	  const delivery = deliveryFor(declaration);
143	
144	  // THE TARGET. Which branch this run pushes to, and which pull request it delivers
145	  // on, is the executor's decision: the task declares `supersede_existing_pr`, the
146	  // executor resolved it before this subprocess started — this cycle's own fresh
147	  // branch, with the last cycle's pull request closed once this one's exists (or
148	  // landed first, where it had concluded green) — and handed it in. Nothing here
149	  // reads the open pull requests or picks a name.
150	  //
151	  // That disposal is what keeps a member that cannot land from accumulating a line
152	  // of obsolete pull requests, one a night: the converge is a full recompute from
153	  // the base, so the one left standing is always this cycle's answer.
154	  const targetBranch = process.env.CLAUDINITE_TARGET_BRANCH || null;
155	  const targetPr = process.env.CLAUDINITE_TARGET_PR || null;
156	  if (!targetBranch) {
157	    // AN EXECUTOR THAT PREDATES THE HAND-OFF sets no target, and then the disposal
158	    // this worker used to do on its own still has to happen, or incumbents pile up
159	    // (#787): a cycle that could not land its PR leaves it open for the next run,
160	    // and that disposal must precede the converge, because a cycle with nothing to
161	    // do returns early. Held for the convergence window #1698 closes.
162	    // @legacy-tolerance advisory:none retire:#1698
163	    const open = rehearsalRef ? { json: [] } : await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
164	    const incumbent = openDeliveredPull(open.json, UPDATE_PREFIX);
165	    if (incumbent) {
166	      const disposal = await disposeOpenPull({
167	        task: UPDATE_TASK_ID,
168	        token, repo, pr: incumbent, delivery, log: (s) => console.log(`update: ${s}`),
169	      }).catch((e) => { console.log(`update: disposing of PR #${incumbent.number} failed: ${e.message}`); return 'kept'; });
170	      if (disposal === 'kept') {
171	        console.log(`update: PR #${incumbent.number} still stands — this cycle cannot deliver on top of it`);
172	        return;
173	      }
174	      if (disposal === 'merged') {
175	        console.log(`update: landed PR #${incumbent.number}; main has moved past this checkout — next cycle converges from it`);
176	        return;
177	      }
178	    }
179	  }
180	
181	  // The flows run from a FRESH CANON CLONE, never from this repo's mount: the mount is
182	  // the thing being replaced, and a flow executing its own stale copy is how a broken
183	  // update makes itself permanent.
184	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
185	  try {
186	    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
187	    // default branch, which is the only thing a member should ever converge onto.
188	    git(rehearsalRef
189	      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
190	      : ['clone', '--depth', '1', CANON_URL, tmp]);
191	    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
192	    const { engineUpdate } = await load('packs/claudinite-lifecycle/updates/engine-update.mjs');
193	    const { packUpdate } = await load('packs/claudinite-lifecycle/updates/pack-update.mjs');
194	    const { terminalFor } = await load('packs/claudinite-lifecycle/updates/terminals.mjs');
195	
196	    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
197	    // pack flow enforces that against what this repo HAS. Running packs first would
198	    // check every pack against yesterday's engine and block updates that the very
199	    // next step would have made legal.
200	    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
201	    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
202	    let packs = null;
203	    if (engine.status !== 'needs-human') {
204	      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
205	      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
206	    }
207	
208	    // The engine's terminal wins when it stopped the run: nothing downstream of a
209	    // refused engine update is trustworthy, including a pack flow that never ran.
210	    const outcome = engine.status === 'needs-human' ? engine : packs;
211	    const terminal = terminalFor(outcome);
212	
213	    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
214	    // canon ref converge this member and leave it green — so it says so and puts the
215	    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
216	    // converge left behind would be picked up by the canary's own next cycle as if a
217	    // human had written it.
218	    if (rehearsalRef) {
219	      git(['-C', root, 'checkout', '--', '.']);
220	      git(['-C', root, 'clean', '-fd']);
221	      if (terminal.action === 'needs-human') {
222	        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
223	        process.exit(1);
224	      }
225	      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
226	      return;
227	    }
228	
229	    // AN APPLY STAGE IS NOT "NOTHING CHANGED" (#1545). A run that withheld a workflow
230	    // file leaves the pack unstamped, precisely so the record stays in range — so on a
231	    // cycle that re-stages content the branch already carries, the tree can be clean
232	    // while a delivery is still owed. Returning here would skip the PR, and the
233	    // apply-stage request is written below it, so nobody would ever be asked to deliver:
