274	    // pull request READ back carries the previous cycle's sha, and polling that one
275	    // waits on runs that will never come — while on the cycle that pushed nothing,
276	    // the sha with the checks on it is the one already standing.
277	    const head = pushed ? git(['-C', root, 'rev-parse', 'HEAD']).trim() : standing.sha;
