293	      console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);
294	    }
295	    pr = { ...pr, head: { ...pr.head, ref: branch, sha: head } };
296	
297	    // The terminal, acted on. Only one action merges, and it is the one the flow
298	    // already judged green — everything else leaves the PR standing, labelled or
